import{_ as i,a0 as o,w as s,s as l,ao as u,I as r,x as e,a1 as p,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"红帽 CEO 对 OpenStack 收益表示乐观 | LCTT x X-CMD","titleTemplate":false,"description":"红帽 CEO 对 OpenStack 收益表示乐观 | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"红帽 CEO 对 OpenStack 收益表示乐观 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"红帽 CEO 对 OpenStack 收益表示乐观 | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20150921 Red Hat CEO Optimistic on OpenStack Revenue Opportunity","title":"红帽 CEO 对 OpenStack 收益表示乐观","tag":"201510","desc":""},"relativePath":"201510/20150921 Red Hat CEO Optimistic on OpenStack Revenue Opportunity.md","filePath":"[post].md"}'),O={name:"201510/20150921 Red Hat CEO Optimistic on OpenStack Revenue Opportunity.md"};function d(m,t,h,k,C,c){const n=o("Link");return s(),l("div",null,[t[13]||(t[13]=u('<h1 id="红帽-ceo-对-openstack-收益表示乐观" tabindex="-1">红帽 CEO 对 OpenStack 收益表示乐观 <a class="header-anchor" href="#红帽-ceo-对-openstack-收益表示乐观" aria-label="Permalink to “红帽 CEO 对 OpenStack 收益表示乐观”">​</a></h1><p>得益于围绕 Linux 和云不断发展的平台与基础设施技术，红帽正在持续快速发展。红帽宣布在九月二十一日完成了 2016 财年第二季度的财务业绩，再次超过预期。</p><p><img src="http://www.serverwatch.com/imagesvr_ce/1212/icon-redhatcloud-r.jpg" alt=""></p><p>这一季度，红帽的收入为 5 亿 4 百万美元，和去年同比增长 13%。净收入为 5 千 1 百万美元，超过了 2015 财年第二季度的 4 千 7 百万美元。</p><p>展望未来，红帽为下一季度和全年提供了积极的目标。对于第三季度，红帽希望指导收益能在 5亿1千9百万美元和5亿2千3百万美元之间，和去年同期相比增长 15%。</p><p>对于 2016 财年，红帽的全年指导目标是 20亿4千4百万美元，和去年相比增长 14%。</p><p>红帽 CFO Frank Calderoni 在电话会议上指出，红帽最高的 30 个订单差不多甚至超过了 1 百万美元。其中有 4 个订单超过 5 百万美元，还有一个超过 1 千万美元。</p><p>从近几年的经验来看，红帽产品的交叉销售非常成功，全部订单中有超过 65% 的订单包括了一个或多个红帽应用和新兴技术产品组件。</p><p>Calderoni 说 “我们希望这些技术，例如中间件、RHEL OpenStack 平台、OpenShift、云管理和存储能持续推动收益增长。”</p><h3 id="openstack" tabindex="-1">OpenStack <a class="header-anchor" href="#openstack" aria-label="Permalink to “OpenStack”">​</a></h3><p>在电话会议中，红帽 CEO Jim Whitehurst 多次问到 OpenStack 的预期收入。Whitehurst 说得益于安装程序的改进，最近发布的 Red Hat OpenStack Platform 7.0 向前垮了一大步。</p><p>Whitehurst 提到：“在识别硬件和使用方面它做的很好，当然，这也意味着在硬件识别并正确使用它们方便还有很多工作要做。”</p><p>Whitehurst 说他已经开始注意到很多的生产应用程序开始迁移到 OpenStack 云上来。他也警告说在产业化方面迁移到 OpenStack 大部分只是尝鲜，还并没有成为主流。</p><p>对于竞争对手， Whitehurst 尤其提到了微软、惠普和 Mirantis。在他看来，很多组织仍然会使用多种操作系统，如果他们部分使用了微软产品，会更倾向于开源方案作为替代选项。Whitehurst 说在云方面他还没有看到太多和惠普面对面的竞争，但和 Mirantis 则确实如此。</p><p>Whitehurst 说 “我们也有几次胜利，客户从 Mirantis 转到了 RHEL。”</p><hr>',16)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),p(n,{href:"http://www.serverwatch.com/server-news/red-hat-ceo-optimistic-on-openstack-revenue-opportunity.html"},{default:a(()=>[...t[0]||(t[0]=[e("http://www.serverwatch.com/server-news/red-hat-ceo-optimistic-on-openstack-revenue-opportunity.html",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=e("作者：",-1)),p(n,{href:"http://www.serverwatch.com/author/Sean-Michael-Kerner-101580.htm"},{default:a(()=>[...t[2]||(t[2]=[e("Sean Michael Kerner",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),p(n,{href:"http://mutouxiaogui.cn/blog"},{default:a(()=>[...t[3]||(t[3]=[e("ictlyh",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),p(n,{href:"https://github.com/wxy"},{default:a(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=e("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创编译，",-1)),p(n,{href:"https://linux.cn/"},{default:a(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const w=i(O,[["render",d]]);export{T as __pageData,w as default};
